def vincular_sedes_existentes(apps, schema_editor):
    """Normaliza la sede textual sin corregir ni fusionar sus nombres."""
    Puesto = apps.get_model('inventario', 'Puesto')
    Sede = apps.get_model('inventario', 'Sede')
    alias = schema_editor.connection.alias

    puestos = list(
        Puesto.objects.using(alias)
        .exclude(sede__isnull=True)
        .exclude(sede='')
        .order_by('pk')
        .values_list('pk', 'cliente_id', 'sede')
    )
    for puesto_id, cliente_id, nombre in puestos:
        sede, _ = Sede.objects.using(alias).get_or_create(
            cliente_id=cliente_id,
            nombre=nombre,
        )
        Puesto.objects.using(alias).filter(pk=puesto_id).update(
            sede_catalogo_id=sede.pk
        )


